    <div className="relative min-h-[calc(100vh-80px)] py-24 px-4 max-w-7xl mx-auto">
      <StaggerContainer>
        <AnimatedItem animation="popIn">
          <Text as="h2" className="text-4xl sm:text-5xl font-extrabold text-center mb-16 uppercase">
